"use client";

import Image from "next/image";
import { useRef, useState } from "react";
import { ArrowLeft, ArrowRight, Loader2, Upload, X } from "lucide-react";
import { cn } from "@/lib/utils";

export type UploadedMedia = { url: string; alt: string };
type Folder = "products" | "gallery" | "banners" | "categories";

export async function uploadFile(file: File, folder: Folder): Promise<{ url: string; kind: "IMAGE" | "VIDEO" }> {
  const body = new FormData();
  body.append("file", file);
  body.append("folder", folder);
  const res = await fetch("/api/admin/upload", { method: "POST", body });
  const json = await res.json();
  if (!res.ok) throw new Error(json.error ?? "Upload failed");
  return json;
}

/** Multi-image uploader with drag & drop, reordering (first image = main image) and alt text. */
export function MediaUploader({ value, onChange, folder = "products", max = 12 }: { value: UploadedMedia[]; onChange: (v: UploadedMedia[]) => void; folder?: Folder; max?: number }) {
  const input = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [drag, setDrag] = useState(false);

  async function handle(files: FileList | null) {
    if (!files?.length) return;
    setError(null);
    const list = Array.from(files).slice(0, max - value.length);
    setBusy(list.length);
    const added: UploadedMedia[] = [];
    for (const f of list) {
      try {
        const r = await uploadFile(f, folder);
        added.push({ url: r.url, alt: "" });
      } catch (e) {
        setError((e as Error).message);
      }
      setBusy((b) => b - 1);
    }
    onChange([...value, ...added]);
  }

  const move = (i: number, dir: -1 | 1) => {
    const next = [...value];
    const j = i + dir;
    if (j < 0 || j >= next.length) return;
    [next[i], next[j]] = [next[j], next[i]];
    onChange(next);
  };

  return (
    <div>
      <div className="grid grid-cols-3 gap-3 sm:grid-cols-4 lg:grid-cols-6">
        {value.map((m, i) => (
          <div key={m.url} className={cn("group relative rounded-md border bg-paper", i === 0 ? "border-brass ring-2 ring-brass/30" : "border-line")}>
            <div className="relative aspect-square"><Image src={m.url} alt={m.alt} fill sizes="120px" className="object-contain p-1" /></div>
            {i === 0 && <span className="absolute left-1 top-1 rounded bg-brass px-1.5 text-[10px] font-bold text-white">MAIN</span>}
            <div className="absolute right-1 top-1 flex gap-0.5 opacity-0 transition group-hover:opacity-100 group-focus-within:opacity-100">
              <button type="button" onClick={() => move(i, -1)} className="rounded bg-white/90 p-0.5" aria-label="Move left"><ArrowLeft className="h-3.5 w-3.5" /></button>
              <button type="button" onClick={() => move(i, 1)} className="rounded bg-white/90 p-0.5" aria-label="Move right"><ArrowRight className="h-3.5 w-3.5" /></button>
              <button type="button" onClick={() => onChange(value.filter((_, x) => x !== i))} className="rounded bg-white/90 p-0.5 text-danger" aria-label="Remove image"><X className="h-3.5 w-3.5" /></button>
            </div>
            <input value={m.alt} onChange={(e) => onChange(value.map((v, x) => (x === i ? { ...v, alt: e.target.value.slice(0, 160) } : v)))} placeholder="Alt text" className="w-full border-t border-line bg-white px-1.5 py-1 text-[11px] outline-none" />
          </div>
        ))}
        {value.length < max && (
          <button
            type="button"
            onClick={() => input.current?.click()}
            onDragOver={(e) => { e.preventDefault(); setDrag(true); }}
            onDragLeave={() => setDrag(false)}
            onDrop={(e) => { e.preventDefault(); setDrag(false); void handle(e.dataTransfer.files); }}
            className={cn("flex aspect-square flex-col items-center justify-center gap-1 rounded-md border-2 border-dashed text-xs text-muted transition", drag ? "border-brass bg-brass-light/50" : "border-line hover:border-brass")}
          >
            {busy > 0 ? <Loader2 className="h-6 w-6 animate-spin" /> : <Upload className="h-6 w-6" />}
            {busy > 0 ? `Uploading ${busy}…` : "Add photos"}
          </button>
        )}
      </div>
      <input ref={input} type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif,image/heic" multiple hidden onChange={(e) => { void handle(e.target.files); e.target.value = ""; }} />
      <p className="mt-2 text-xs text-muted">JPG, PNG, WebP or HEIC up to 8 MB each. Images are auto-resized, converted to WebP and stripped of location metadata. First image is the main listing photo.</p>
      {error && <p className="mt-1 text-xs text-danger">{error}</p>}
    </div>
  );
}
